import sys

def ipo_brute(k, w, profits, capital):
    n = len(profits)
    done = [False] * n
    for _ in range(k):
        best = -1
        best_i = -1
        for i in range(n):
            if not done[i] and capital[i] <= w:
                if profits[i] > best:
                    best = profits[i]
                    best_i = i
        if best_i == -1:
            break
        w += best
        done[best_i] = True
    return w

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n, k, w = int(data[0]), int(data[1]), int(data[2])
    profits = [int(x) for x in data[3:3 + n]]
    capital = [int(x) for x in data[3 + n:3 + 2 * n]]
    print(ipo_brute(k, w, profits, capital))
